    static int match(byte[] gray,int width,int left,int top,int right,int bottom) {
        if(right<=left||bottom<=top)return 0;
        float aspect=(right-left+1)/(float)(bottom-top+1);boolean[] mask=new boolean[W*H],nearest=new boolean[W*H];
        for(int y=0;y<H;y++)for(int x=0;x<W;x++) {
            float sx=left+(x+.5f)*(right-left+1)/W-.5f,sy=top+(y+.5f)*(bottom-top+1)/H-.5f;
            int nx=Math.max(left,Math.min(right,Math.round(sx))),ny=Math.max(top,Math.min(bottom,Math.round(sy)));
            nearest[y*W+x]=(gray[ny*width+nx]&255)<165;
            int x0=(int)Math.floor(sx),y0=(int)Math.floor(sy);
            float dx=sx-x0,dy=sy-y0;
            int x1=Math.max(left,Math.min(right,x0+1)),y1=Math.max(top,Math.min(bottom,y0+1));
            x0=Math.max(left,Math.min(right,x0));y0=Math.max(top,Math.min(bottom,y0));
            float upper=(gray[y0*width+x0]&255)*(1-dx)+(gray[y0*width+x1]&255)*dx;
            float lower=(gray[y1*width+x0]&255)*(1-dx)+(gray[y1*width+x1]&255)*dx;
            mask[y*W+x]=upper*(1-dy)+lower*dy<165;
        }
        float[] scores=new float[5];
        for(var t:TEMPLATES) {
            float ratio=(float)Math.abs(Math.log(aspect/t.aspect));if(ratio>.45f)continue;
            int intersection=0,union=0,nearIntersection=0,nearUnion=0;
            for(int i=0;i<mask.length;i++) {
                boolean ink=(t.bits[i/8]&(1<<(7-i%8)))!=0;
                if(ink&&mask[i])intersection++;
                if(ink||mask[i])union++;
                if(ink&&nearest[i])nearIntersection++;
                if(ink||nearest[i])nearUnion++;
            }
            float score=Math.max(intersection/(float)Math.max(1,union),nearIntersection/(float)Math.max(1,nearUnion))-ratio*.15f;
            scores[t.shift+2]=Math.max(scores[t.shift+2],score);
        }
        int best=2;float first=0,second=0;
        for(int i=0;i<scores.length;i++)if(scores[i]>first){second=first;first=scores[i];best=i;}else second=Math.max(second,scores[i]);
        return first>=.58f&&first-second>=.09f?best-2:0;
    }
